// The two EIA calls run in sequence, so the crude oil reply is read from its node by name.
const oilPayload = $('EIA Crude Oil (Brent + WTI)').first().json;
const gasPayload = $json;

const dataRows = (payload) => {
  if (!payload || !payload.response || !Array.isArray(payload.response.data)) return [];
  return payload.response.data;
};

const pickSeries = (rows, seriesCode) => {
  if (rows.length === 0) return null;
  const match = rows.find((row) => row.series === seriesCode) || rows[0];
  const value = Number(match.value);
  return Number.isFinite(value) ? value : null;
};

const now = new Date();
const pad = (n) => String(n).padStart(2, '0');
const dateKey = now.getFullYear() + '-' + pad(now.getMonth() + 1) + '-' + pad(now.getDate());

const oilRows = dataRows(oilPayload);
const gasRows = dataRows(gasPayload);

return [
  {
    json: {
      date: dateKey,
      fetched_at: now.toISOString(),
      brent_usd: pickSeries(oilRows, 'RBRTE'),
      wti_usd: pickSeries(oilRows, 'RWTC'),
      natgas_usd: pickSeries(gasRows, 'RNGWHHD'),
    },
  },
];

// Compares today's prices with the most recent earlier row of the PriceHistory tab.
const THRESHOLD_PCT = 3;
const today = $('Normalize Prices').first().json;
const history = $input.all().map((item) => item.json);

const pad = (n) => String(n).padStart(2, '0');

const toDateKey = (value) => {
  if (value === undefined || value === null || value === '') return null;
  if (typeof value === 'number') {
    // Google Sheets serial date -> ISO date
    const millis = Math.round((value - 25569) * 86400 * 1000);
    return new Date(millis).toISOString().slice(0, 10);
  }
  const text = String(value).trim().split('/').join('-');
  const parsed = new Date(text);
  if (!Number.isNaN(parsed.getTime())) {
    return parsed.getFullYear() + '-' + pad(parsed.getMonth() + 1) + '-' + pad(parsed.getDate());
  }
  return text.slice(0, 10);
};

const toNumber = (value) => {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
};

const previousRows = history
  .map((row) => ({ date: toDateKey(row.date), row }))
  .filter((entry) => entry.date && entry.date < today.date)
  .sort((a, b) => (a.date < b.date ? 1 : -1));

const previous = previousRows.length > 0 ? previousRows[0] : null;
const previousRow = previous ? previous.row : {};

const changePct = (current, before) => {
  const base = toNumber(before);
  if (current === null || base === null || base === 0) return null;
  return ((current - base) / base) * 100;
};

const brentChange = changePct(today.brent_usd, previousRow.brent_usd);
const wtiChange = changePct(today.wti_usd, previousRow.wti_usd);
const natgasChange = changePct(today.natgas_usd, previousRow.natgas_usd);

const formatPrice = (value) => (value === null ? 'n/a' : '$' + value.toFixed(2));
const formatChange = (value) => (value === null ? 'n/a' : (value >= 0 ? '+' : '') + value.toFixed(2) + '%');

const moves = [
  { label: 'Brent', price: today.brent_usd, change: brentChange },
  { label: 'WTI', price: today.wti_usd, change: wtiChange },
  { label: 'Henry Hub gas', price: today.natgas_usd, change: natgasChange },
];

const alerts = moves.filter((move) => move.change !== null && Math.abs(move.change) > THRESHOLD_PCT);
const previousLabel = previous ? previous.date : 'no earlier row';

const briefingLines = [
  ':oil_drum: *Daily oil and gas price briefing - ' + today.date + '*',
].concat(
  moves.map((move) => '- ' + move.label + ': ' + formatPrice(move.price) + ' (' + formatChange(move.change) + ' vs ' + previousLabel + ')'),
  [alerts.length === 0 ? '_No move beyond ' + THRESHOLD_PCT + '%.' : ':warning: ' + alerts.length + ' move(s) beyond ' + THRESHOLD_PCT + '%.'],
);

const urgentLines = [
  ':rotating_light: *Price move alert - ' + today.date + '*',
].concat(
  alerts.map((move) => '- *' + move.label + '*: ' + formatPrice(move.price) + ' (' + formatChange(move.change) + ')'),
  ['Check market exposure, hedging position and the trading desk.'],
);

return [
  {
    json: {
      date: today.date,
      brent_usd: today.brent_usd,
      wti_usd: today.wti_usd,
      natgas_usd: today.natgas_usd,
      brent_change_pct: brentChange,
      wti_change_pct: wtiChange,
      natgas_change_pct: natgasChange,
      previous_date: previous ? previous.date : null,
      alert_count: alerts.length,
      any_price_alert: alerts.length > 0,
      briefing: briefingLines.join('\n'),
      urgent_message: urgentLines.join('\n'),
    },
  },
];
